// ─── Validation et Enrichissement de la Réservation d'Essai ───
const payload = $input.first().json.body || $input.first().json;

const fullName = payload.full_name || 'Client Wakala';
const rawPhone = payload.phone_number || '';
const email = payload.email || null;
const city = payload.city || 'Casablanca';
const vehicleName = payload.vehicle_name || payload.trim_name || 'Véhicule Neuf';
const brand = payload.brand || payload.brand_name || 'Marque Officielle';
const preferredDate = payload.preferred_date || new Date(Date.now() + 86400000 * 2).toISOString().split('T')[0];
const showroomName = payload.showroom_name || `Concessionnaire Officiel ${brand} ${city}`;
const showroomAddress = payload.showroom_address || `Centre Automobile Agréé, ${city}`;

// Génération de la référence unique de réservation marocaine
const cityCode = city.substring(0, 3).toUpperCase();
const randomSuffix = Math.floor(1000 + Math.random() * 9000);
const bookingReference = `TD-${new Date().getFullYear()}-${cityCode}-${randomSuffix}`;

// Normalisation E.164 Téléphone Marocain (+212...)
let cleanPhone = rawPhone.replace(/[^0-9+]/g, '');
if (cleanPhone.startsWith('0')) {
  cleanPhone = '+212' + cleanPhone.substring(1);
} else if (!cleanPhone.startsWith('+')) {
  cleanPhone = '+' + cleanPhone;
}

// Message WhatsApp / SMS client bilingue
const whatsappMessage = `🚗 *WAKALA MAROC — Confirmation de Demande d'Essai*\n\nBonjour *${fullName}*,\n\nVotre réservation d'essai sur route pour la *${brand} ${vehicleName}* est bien enregistrée !\n\n📍 *Showroom :* ${showroomName} (${showroomAddress})\n📅 *Date souhaitée :* ${preferredDate}\n🔖 *Réf. dossier :* ${bookingReference}\n\nUn conseiller commercial prendra contact avec vous dans un délai de 2h ouvrées pour valider l'horaire précis.\n\n*Conformité CNDP Loi n° 09-08 — Wakala.ma*`;

return [{
  json: {
    bookingReference,
    fullName,
    cleanPhone,
    email,
    city,
    vehicleName,
    brand,
    preferredDate,
    showroomName,
    showroomAddress,
    whatsappMessage,
    receivedAt: new Date().toISOString(),
    cndpConsent: payload.cndp_consent_accepted ?? true
  }
}];
